alter table public.character_saves drop constraint character_saves_snapshot_check; alter table public.character_saves add constraint character_saves_snapshot_check check ((jsonb_typeof(snapshot) = 'object' and snapshot->>'format' = 'dndcard-snapshot' and snapshot->>'scope' = 'full' and snapshot->>'version' = '1' and jsonb_typeof(snapshot#>'{payload,manager}') = 'object' and jsonb_typeof(snapshot#>'{payload,state}') = 'object' and octet_length(snapshot::text) <= 2097152) is true);
